changeSet.sql:
ALTER TABLE project ENABLE ROW LEVEL SECURITY;
ALTER TABLE library ENABLE ROW LEVEL SECURITY;
ALTER TABLE dependency ENABLE ROW LEVEL SECURITY;
ALTER TABLE upload ENABLE ROW LEVEL SECURITY;
ALTER TABLE license ENABLE ROW LEVEL SECURITY;
ALTER TABLE license_risk ENABLE ROW LEVEL SECURITY;
ALTER TABLE requirement ENABLE ROW LEVEL SECURITY;
ALTER TABLE license_per_library ENABLE ROW LEVEL SECURITY;
ALTER TABLE license_conflict ENABLE ROW LEVEL SECURITY;
ALTER TABLE generic_license_url ENABLE ROW LEVEL SECURITY;
ALTER TABLE license_naming_mapping ENABLE ROW LEVEL SECURITY;
ALTER TABLE library_error_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE fossology ENABLE ROW LEVEL SECURITY;

CREATE POLICY authenticated_access ON project
    FOR ALL
    USING (
        current_setting('request.jwt.claim.role', true) = 'service_role'
        OR current_setting('request.jwt.claim.sub', true) IS NOT NULL
    )
    WITH CHECK (
        current_setting('request.jwt.claim.role', true) = 'service_role'
        OR current_setting('request.jwt.claim.sub', true) IS NOT NULL
    );

